require_once __DIR__.'/../config.php'; require_once __DIR__.'/../includes/functions.php'; $pageTitle='Attendance'; require_role(['admin']); require_once __DIR__.'/../includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$date=$_POST['attendance_date'];foreach($_POST['status']??[] as $sid=>$status){$st=$pdo->prepare("SELECT class_id FROM students WHERE id=?");$st->execute([(int)$sid]);$class=$st->fetchColumn();$q=$pdo->prepare("INSERT INTO attendance(student_id,class_id,attendance_date,status,note,recorded_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),note=VALUES(note),recorded_by=VALUES(recorded_by),class_id=VALUES(class_id)");$q->execute([(int)$sid,$class,$date,$status,null,user()['id']]);}audit($pdo,'save','attendance',null,$date);$saved=true;}
$date=$_GET['date']??date('Y-m-d');$students=$pdo->query("SELECT s.id,s.admission_no,s.surname,s.firstname,c.name class_name,c.section FROM students s LEFT JOIN classes c ON c.id=s.class_id WHERE s.status='active' ORDER BY c.name,s.surname")->fetchAll();
?><h2>Attendance</h2><?php if(!empty($saved)): ?><div class="alert alert-success">Attendance saved.</div><?php endif;?><div class="card p-4"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="mb-3"><label>Date</label><input class="form-control" type="date" name="attendance_date" value="<?=e($date)?>" required></div><div class="table-responsive"><table class="table"><thead><tr><th>Student</th><th>Class</th><th>Status</th></tr></thead><tbody><?php foreach($students as $s): ?><tr><td><?=e($s['admission_no'].' — '.$s['surname'].' '.$s['firstname'])?></td><td><?=e(trim(($s['class_name']??'').' '.($s['section']??'')))?></td><td><select class="form-select" name="status[<?=$s['id']?>]"><option value="present">Present</option><option value="absent">Absent</option><option value="late">Late</option><option value="excused">Excused</option></select></td></tr><?php endforeach;?></tbody></table></div><button class="btn btn-primary">Save attendance</button></form></div>
